class _ScannerState extends State<Scanner>{static const channel=MethodChannel('com.sqile/security');bool busy=false;Map<String,dynamic>? data;String? error;Future<void> scan()async{setState(()=>{busy=true,data=null,error=null});try{final f=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['apk']);if(f==null||f.files.single.path==null)return;final r=await channel.invokeMethod<Map>('scanApk',{'path':f.files.single.path});if(r==null)throw Exception('Tidak ada hasil');data=Map<String,dynamic>.from(r);}on PlatformException catch(e){error=e.message??'Pemindaian gagal';}catch(e){error='Gagal: $e';}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(18),children:[const Text('APK Scanner',style:TextStyle(fontSize:25,fontWeight:FontWeight.w800)),const SizedBox(height:7),const Text('Pilih APK yang sudah diunduh untuk meninjau metadata dan izin sebelum instalasi.',style:TextStyle(color:muted,height:1.4)),const SizedBox(height:18),SizedBox(height:52,child:FilledButton.icon(onPressed:busy?null:scan,icon:const Icon(Icons.file_open),label:Text(busy?'Memindai...':'Pilih dan periksa APK'),style:FilledButton.styleFrom(backgroundColor:purple,foregroundColor:bg,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(15))))),if(error!=null)Padding(padding:const EdgeInsets.only(top:14),child:Text(error!,style:const TextStyle(color:Colors.redAccent))),if(data!=null)...[const SizedBox(height:16),Info(icon:Icons.shield_outlined,title:'Risiko ${data!['risk']}',body:'${data!['appName']}\nPaket: ${data!['packageName']}\nVersi: ${data!['versionName']}'),const SizedBox(height:12),const Text('Izin yang diminta',style:TextStyle(fontSize:17,fontWeight:FontWeight.bold)),...((data!['permissions'] as List? ?? []).map((p)=>Padding(padding:const EdgeInsets.only(top:8),child:Info(icon:Icons.key_outlined,title:p.toString(),body:''))),const SizedBox(height:10),const Text('Penilaian izin adalah heuristik, bukan bukti APK aman atau berbahaya.',style:TextStyle(color:muted,fontSize:12))],const SizedBox(height:16),const Info(icon:Icons.info_outline,title:'Batasan Android',body:'Sqile tidak mengambil alih dialog unduhan Chrome. Pilih APK dari penyimpanan untuk memeriksanya.')]);}
